use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn main () -> Result < () > { let matches = Command :: new ("rust-to-monster-simple") . version ("0.1.0") . about ("Generate simplified Rust to Monster Group transformation report") . arg (Arg :: new ("input") . short ('i') . long ("input") . value_name ("DIR") . help ("Input directory with Rust declarations") . required (true)) . arg (Arg :: new ("output") . short ('o') . long ("output") . value_name ("FILE") . help ("Output file for the epic report") . default_value ("RUST_TO_MONSTER_REPORT.md")) . get_matches () ; let input_dir = matches . get_one :: < String > ("input") . unwrap () ; let output_file = matches . get_one :: < String > ("output") . unwrap () ; println ! ("👹 Generating EPIC Rust to Monster Group Transformation Report...") ; println ! ("📂 Analyzing: {}" , input_dir) ; let mut signature_frequencies : HashMap < String , u64 > = HashMap :: new () ; let mut processed_files = 0 ; if let Ok (paths) = fs :: read_dir (input_dir) { for path in paths { if let Ok (path) = path { let path = path . path () ; if path . extension () . and_then (| s | s . to_str ()) == Some ("rs") { if let Ok (content) = fs :: read_to_string (& path) { let signature = extract_signature_from_content (& content) ; if ! signature . is_empty () { * signature_frequencies . entry (signature) . or_insert (0) += 1 ; processed_files += 1 ; } } } } } } println ! ("✅ Processed {} files" , processed_files) ; println ! ("🔄 Generating Monster Group analysis...") ; let report = generate_epic_monster_report (& signature_frequencies , processed_files) ; fs :: write (output_file , report) ? ; println ! ("🎉 EPIC SUCCESS!") ; println ! ("👹 Rust to Monster Group Transformation Report written to: {}" , output_file) ; println ! ("📊 Total unique signatures: {}" , signature_frequencies . len ()) ; println ! ("🔢 Total declarations processed: {}" , signature_frequencies . values () . sum ::< u64 > ()) ; Ok (()) }
}